const privacy = (what: string) =>
  "Your photo is processed only to create " + what + ", and you can delete it afterward. Use the delete option on your result or in your history, and the upload is removed. Avoid sending photos that show other people, documents or anything you would not want processed.";

const consent = (what: string) =>
  "Only if they are an adult and have said yes. Using someone else's photo for " + what + " without their permission is not okay, and the tool is for adults aged 18 and over. If you are unsure, ask first or use a photo of yourself.";

const free = (what: string) =>
  "Yes, you can try " + what + " free. New accounts get free credits to run a preview, and each preview uses a small number of credits. If you want to keep going after that, you can top up or upgrade, but nothing is needed to try your first result.";

